const markets = [
  { location: 'Buenos Aires, Argentina', country_code: 'AR' },
  { location: 'Ciudad de México, México', country_code: 'MX' },
  { location: 'Santiago, Chile', country_code: 'CL' },
  { location: 'Bogotá, Colombia', country_code: 'CO' },
  { location: 'Lima, Perú', country_code: 'PE' },
  { location: 'Montevideo, Uruguay', country_code: 'UY' },
  { location: 'San José, Costa Rica', country_code: 'CR' },
];
const verticals = [
  { key: 'marketing_agency', queries: ['agencia de marketing digital', 'agencia de publicidad'] },
  { key: 'growth_agency', queries: ['agencia growth marketing', 'agencia performance marketing'] },
  { key: 'creative_agency', queries: ['agencia creativa branding', 'agencia de diseño digital'] },
  { key: 'general_agency', queries: ['agencia de servicios digitales', 'agencia desarrollo web'] },
];
const queries = verticals.flatMap(vertical => markets.flatMap(market => vertical.queries.map(query => ({ vertical: vertical.key, province: market.location, country_code: market.country_code, search: `${query} en ${market.location}` }))));
return [{ json: { queries, searchStringsArray: queries.map(item => item.search), requested_limit: 200, verticals: verticals.map(item => item.key) } }];

const raw = Array.isArray($json) ? $json : (Array.isArray($json.body) ? $json.body : []);
const cleanDomain = value => { try { const host = new URL(value).hostname.toLowerCase().replace(/^www\./, ''); return /^(facebook|instagram|linkedin|x)\.com$/.test(host) ? null : host; } catch { return null; } };
const allowedCountries = new Set(['AR','MX','CL','CO','PE','UY','CR']);
const countryAliases = { ARG: 'AR', ARGENTINA: 'AR', MEXICO: 'MX', 'MÉXICO': 'MX', CHILE: 'CL', COLOMBIA: 'CO', PERU: 'PE', 'PERÚ': 'PE', URUGUAY: 'UY', 'COSTA RICA': 'CR' };
const relevant = /(agencia|marketing|publicidad|comunicaci[oó]n|digital|growth|performance|creativ|branding|dise[nñ]o|desarrollo web)/i;
const excluded = /(automotor|concesion|viajes|turismo|inmobiliari|empleo|modelos)/i;
const seenPlaces = new Set(); const seenDomains = new Set(); const leads = [];
for (const place of raw) {
  const placeId = String(place.placeId || place.place_id || place.cid || '').trim();
  const name = String(place.title || place.name || '').trim();
  const category = String(place.categoryName || place.category || '').trim();
  const address = String(place.address || place.street || '').trim();
  const rawCountry = String(place.countryCode || place.country || '').toUpperCase();
  const countryCode = countryAliases[rawCountry] || rawCountry;
  const closed = Boolean(place.permanentlyClosed || place.temporarilyClosed) || /permanently_closed|cerrado permanentemente/i.test(String(place.status || ''));
  const classificationText = `${name} ${category} ${place.searchString || ''}`;
  if (!placeId || !name || closed || !allowedCountries.has(countryCode) || !relevant.test(classificationText) || excluded.test(classificationText)) continue;
  const domain = cleanDomain(place.website || place.url);
  if (seenPlaces.has(placeId) || (domain && seenDomains.has(domain))) continue;
  seenPlaces.add(placeId); if (domain) seenDomains.add(domain);
  const vertical = /growth|performance/i.test(classificationText) ? 'growth_agency' : /creativ|branding|dise[nñ]o/i.test(classificationText) ? 'creative_agency' : /marketing|publicidad|digital/i.test(classificationText) ? 'marketing_agency' : 'general_agency';
  leads.push({ source: 'apify_google_places', source_record_id: placeId, place_id: placeId, vertical, business_name: name, category, country_code: countryCode, province: String(place.state || place.region || ''), city: String(place.city || ''), address, phone: String(place.phone || place.phoneUnformatted || ''), website: domain ? `https://${domain}` : null, normalized_domain: domain, public_email: null, maps_url: String(place.url || place.googleMapsUrl || ''), rating: Number.isFinite(Number(place.totalScore || place.rating)) ? Number(place.totalScore || place.rating) : null, review_count: Number.isFinite(Number(place.reviewsCount || place.reviewCount)) ? Number(place.reviewsCount || place.reviewCount) : null, signals: { maps_category: category, has_website: Boolean(domain) }, evidence: [{ type: 'google_places', url: String(place.url || place.googleMapsUrl || ''), observed_at: new Date().toISOString() }] });
  if (leads.length >= 200) break;
}
return leads.length ? [{ json: { leads, result_count: raw.length, discarded_count: Math.max(0, raw.length - leads.length), estimated_cost_usd: Number((raw.length * 0.0015).toFixed(4)), run_id: (Array.isArray($node['Create Prospect Run'].json) ? $node['Create Prospect Run'].json[0]?.id : $node['Create Prospect Run'].json.id) } }] : [];

const rows = Array.isArray($json) ? $json : ($json.body || []);
const existingIds = new Set(rows.map(row => row.source_record_id).filter(Boolean));
const existingDomains = new Set(rows.map(row => row.normalized_domain).filter(Boolean));
const fresh = $node['Normalize and Filter Places'].json.leads.filter(lead => !existingIds.has(lead.source_record_id) && (!lead.normalized_domain || !existingDomains.has(lead.normalized_domain)));
const crawlable = fresh.filter(lead => lead.website && lead.normalized_domain);
return crawlable.map(lead => ({ json: { lead, robots_url: `${lead.website}/robots.txt` } }));

return $input.all().flatMap((item, index) => {
  const source = $node['Dedupe and Prepare Robots'].all()[index]?.json; if (!source?.lead) return [];
  const robots = String(item.json.body ?? item.json.data ?? item.json ?? '');
  const blocked = /user-agent:\s*\*[\s\S]{0,500}?disallow:\s*\/(?:\s|$)/i.test(robots);
  if (blocked) return [];
  const base = source.lead.website.replace(/\/$/, '');
  const paths = ['', '/contacto', '/nosotros'];
  return paths.map(path => ({ json: { lead: source.lead, url: base + path } }));
});

const pages = $input.all(); const requests = $node['Build Allowed Page Requests'].all(); const byDomain = new Map();
const businessRole = /^(info|contacto|contact|ventas|sales|comercial|consultas|hola|hello|newbusiness|negocios|proyectos|partners|webmaster)$/i;
for (let index = 0; index < pages.length; index++) {
  const request = requests[index]?.json; if (!request?.lead?.normalized_domain) continue;
  const body = String(pages[index].json.body ?? pages[index].json.data ?? pages[index].json ?? '').slice(0, 120000);
  if (/ignore (all|previous)|system message|developer message|reveal.*prompt/i.test(body)) continue;
  const text = body.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  const emails = [...new Set((body.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || []).map(value => value.toLowerCase()).filter(value => { const [local, domain] = value.split('@'); return businessRole.test(local) && domain === request.lead.normalized_domain && !/example|test|noreply|no-reply/.test(value); }))];
  const current = byDomain.get(request.lead.normalized_domain) || { lead: request.lead, texts: [], emails: [], urls: [] };
  current.texts.push(text.slice(0, 16000)); current.emails.push(...emails); current.urls.push(request.url); byDomain.set(request.lead.normalized_domain, current);
}
const accounts = [];
for (const current of byDomain.values()) {
  const corpus = current.texts.join(' ');
  const signals = { has_services: /servicios|services|marketing|branding|performance|desarrollo/i.test(corpus), has_case_studies: /casos de [eé]xito|case studies|portfolio|proyectos/i.test(corpus), has_client_signals: /clientes|clients|marcas que conf[ií]an|trusted by/i.test(corpus), has_team: /equipo|team|nosotros|about us/i.test(corpus), has_forms_or_booking: /<form|formulario|agenda|calendly|cal\.com/i.test(corpus), has_technical_delivery: /software|integraci[oó]n|automatizaci[oó]n|api|datos|data/i.test(corpus) };
  let score = 20 + (current.lead.normalized_domain ? 10 : 0) + (current.lead.review_count >= 10 ? 6 : 0) + (current.lead.rating >= 4 ? 4 : 0);
  score += Object.values(signals).filter(Boolean).length * 8; score = Math.min(100, score);
  const publicEmail = [...new Set(current.emails)][0] || null;
  accounts.push({ ...current.lead, public_email: publicEmail, signals, score, status: score >= 55 ? 'qualified' : 'new', evidence: [...current.lead.evidence, ...current.urls.map(url => ({ type: 'public_website', url, observed_at: new Date().toISOString() }))] });
}
return accounts.length ? [{ json: { accounts, duplicate_count: Math.max(0, $node['Normalize and Filter Places'].json.leads.length - $node['Dedupe and Prepare Robots'].all().length), run_id: $node['Normalize and Filter Places'].json.run_id } }] : [];

const match = String($json.output || '').match(/\{[\s\S]*\}/); if (!match) return [];
const value = JSON.parse(match[0]); const account = $node['Prepare Qualified Draft Inputs'].json.account;
const words = String(value.message || '').trim().split(/\s+/).filter(Boolean);
const prohibited = /ahorr|roi|garant|cliente|trabajamos con|resultados|%|experiencia en el sector/i;
if (!value.subject || words.length < 20 || words.length > 120 || prohibited.test(`${value.subject} ${value.message}`)) return [];
return [{ json: { prospect_id: account.id, subject: String(value.subject).slice(0, 180), message: String(value.message).trim(), evidence: account.evidence, status: 'draft' } }];
